using Embix.Search;
using Embix.Search.PgSql;
using Fusi.Tools.Data;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Xunit;

namespace Embix.PgSql.Test;

/// <summary>
/// Runs the queries generated by <see cref="QueryTextClauseBuilder"/> and
/// the query builders on a real PostgreSql database with the Embix schema.
/// </summary>
public sealed class PgSqlQueryTest(PgTestDatabase db)
    : IClassFixture<PgTestDatabase>
{
    private static readonly string[] _tokens =
    [
        "rome", "roma", "romae", "athenai", "αθηναι", "50%", "a_b", "axb",
        "neumagen", "treveri"
    ];

    /// <summary>
    /// Matches tokens with a single operator.
    /// </summary>
    private sealed class TokenQueryBuilder(string connString)
        : PgSqlNonPagedQueryBuilder<(string Field, string Op, string Value)>(connString)
    {
        private readonly QueryTextClauseBuilder _clauses = new();

        public string Table { get; init; } = "eix_token";
        public string Select { get; init; } = "value";

        public override SqlQuery Build((string Field, string Op, string Value) request)
        {
            SqlWhereBuilder where = CreateWhere();
            _clauses.AddClause(where, request.Field, request.Op, request.Value);
            string select = Dialect.QuoteIdentifier(Select);
            return new SqlQuery(
                $"SELECT {select}::text FROM {Dialect.QuoteIdentifier(Table)} " +
                $"{where.ToSql()} ORDER BY {select}",
                where.Parameters);
        }
    }

    public sealed class TokenRequest : PagingOptions
    {
        public string? Prefix { get; set; }
    }

    /// <summary>
    /// Pages the targets of the tokens starting with a prefix, as a typical
    /// client would do.
    /// </summary>
    private sealed class TargetPageBuilder(string connString)
        : PgSqlPagedQueryBuilder<TokenRequest>(connString)
    {
        private readonly QueryTextClauseBuilder _clauses = new();

        public override PagedSqlQuery Build(TokenRequest request)
        {
            SqlWhereBuilder where = CreateWhere();
            if (!string.IsNullOrEmpty(request.Prefix))
                _clauses.AddClause(where, "t.value", "^=", request.Prefix);
            where.Add($"{where.Quote("o.field")} = {where.AddParameter("f")}");

            const string from = "FROM eix_occurrence o " +
                "INNER JOIN eix_token t ON o.token_id = t.id ";
            string paging = BuildPaging(where.Parameters, request);
            return new PagedSqlQuery(
                new SqlQuery($"SELECT DISTINCT o.target_id {from}{where.ToSql()} " +
                    $"ORDER BY o.target_id {paging}", where.Parameters),
                new SqlQuery($"SELECT COUNT(DISTINCT o.target_id) {from}" +
                    where.ToSql(), where.Parameters));
        }
    }

    private bool _initialized;

    private void Init()
    {
        if (_initialized) return;
        db.Reset();
        new PgSqlTableInitializer(db).Initialize(false);
        db.Execute("INSERT INTO eix_token (id, value) VALUES " +
            string.Join(", ", _tokens.Select((t, i) => $"({i + 1}, '{t}')")) +
            ";\nINSERT INTO eix_occurrence (token_id, field, target_id) " +
            "SELECT t.id, 'f', 'r' || lpad(n::text, 2, '0') FROM eix_token t " +
            "CROSS JOIN generate_series(1, 12) n WHERE t.value LIKE 'rom%' " +
            "AND n % (t.id + 1) <> 0;" +
            "\nCREATE TABLE item (id integer PRIMARY KEY, name text, " +
            "n text, flags integer);\n" +
            "INSERT INTO item VALUES (1, 'alpha', '10', 1), (2, 'beta', '12.5', 2)," +
            " (3, 'gamma', '20', 3), (4, 'delta', '-1', 4);\nANALYZE;");
        _initialized = true;
    }

    private static string[] Split(string expected) =>
        expected.Length == 0 ? [] : expected.Split(',');

    [Theory]
    [InlineData("=", "roma", "roma")]
    [InlineData("<>", "roma", "50%,a_b,athenai,axb,neumagen,romae,rome,treveri,αθηναι")]
    [InlineData("*=", "ATH", "athenai")]
    [InlineData("*=", "%", "50%")]
    [InlineData("^=", "rom", "roma,romae,rome")]
    [InlineData("$=", "ae", "romae")]
    [InlineData("?=", "rom?", "roma,rome")]
    [InlineData("?=", "a_*", "a_b")]
    [InlineData("?=", "*er?", "treveri")]
    [InlineData("~=", "^rom(a|ae)$", "roma,romae")]
    // trigram similarities with rome: roma 0.429, romae 0.375
    [InlineData("%=", "rome", "roma,romae,rome")]
    [InlineData("%=", "rome:0.4", "roma,rome")]
    [InlineData("%=", "rome:0.1", "roma,romae,rome")]
    [InlineData("%=", "rome:1", "rome")]
    // neumagen/neumagan: 0.5
    [InlineData("%=", "neumagan:0.45", "neumagen")]
    [InlineData("%=", "neumagan:0.55", "")]
    [InlineData("%=", "αθηνα", "αθηναι")]
    public void TextOperators_Ok(string op, string value, string expected)
    {
        Init();
        TokenQueryBuilder builder = new(db.ConnectionString);
        Assert.Equal(Split(expected),
            builder.Get(("value", op, value), r => r.GetString(0)));
    }

    [Theory]
    [InlineData("n", "==", "12.5", "2")]
    [InlineData("n", "!=", "10", "2,3,4")]
    [InlineData("n", "<", "12.5", "1,4")]
    [InlineData("n", "<=", "12.5", "1,2,4")]
    [InlineData("n", ">", "12.5", "3")]
    [InlineData("n", ">=", "10", "1,2,3")]
    [InlineData("n", "==", "abc", "")]
    [InlineData("flags", ":", "1", "1,3")]
    [InlineData("flags", "&:", "1,2", "3")]
    [InlineData("flags", "!:", "1", "2,4")]
    [InlineData("name", "~=", "^.e", "2,4")]
    public async Task NumericAndBitOperators_Ok(string field, string op,
        string value, string expected)
    {
        Init();
        TokenQueryBuilder builder = new(db.ConnectionString)
        {
            Table = "item",
            Select = "id"
        };
        List<string> ids = await builder.GetAsync((field, op, value),
            r => r.GetString(0), TestContext.Current.CancellationToken);
        // ORDER BY the text of ids: fine for single-digit ids
        Assert.Equal(Split(expected), ids);
    }

    [Fact]
    public async Task PagedBuilder_Ok()
    {
        Init();
        TargetPageBuilder builder = new(db.ConnectionString);
        // occurrences: rome (id 1) has n%2<>0 -> r01,r03..r11; roma (id 2)
        // n%3<>0; romae (id 3) n%4<>0: distinct targets are all but r12
        TokenRequest request = new() { Prefix = "rom", PageNumber = 2, PageSize = 5 };

        DataPage<string> page = await builder.GetPageAsync(request,
            r => r.GetString(0), TestContext.Current.CancellationToken);

        Assert.Equal(11, page.Total);
        Assert.Equal(["r06", "r07", "r08", "r09", "r10"], page.Items);

        // sync, all items
        DataPage<string> all = builder.GetPage(
            new TokenRequest { Prefix = "rom", PageNumber = 1, PageSize = 0 },
            r => r.GetString(0));
        Assert.Equal(11, all.Items.Count);

        // no match: no data query
        DataPage<string> none = builder.GetPage(
            new TokenRequest { Prefix = "zzz", PageNumber = 1, PageSize = 5 },
            r => r.GetString(0));
        Assert.Equal(0, none.Total);
        Assert.Empty(none.Items);
    }

    [Fact]
    public void Scalar_ConvertsCount()
    {
        Init();
        TokenQueryBuilder builder = new(db.ConnectionString);
        SqlParameters p = builder.CreateParameters();
        int count = builder.Scalar<int>(new SqlQuery(
            $"SELECT COUNT(*) FROM eix_token WHERE value LIKE {p.Add("rom%")}", p));
        Assert.Equal(3, count);
        Assert.Null(builder.Scalar<int?>(new SqlQuery("SELECT NULL::int")));
    }

    /// <summary>
    /// A separate database with a realistic volume of data, so that the
    /// planner has real choices to make.
    /// </summary>
    public sealed class VolumeFixture : IDisposable
    {
        public PgTestDatabase Db { get; } = new();

        private bool _initialized;

        public void Init()
        {
            if (_initialized) return;
            Db.Reset();
            new PgSqlTableInitializer(Db).Initialize(false);
            // 20000 tokens, ~10 occurrences each in 5 fields
            Db.Execute("INSERT INTO eix_token (id, value) SELECT n, " +
                "substr(md5(n::text), 1, 4 + n % 8) FROM generate_series(1, 20000) n " +
                "ON CONFLICT DO NOTHING;\n" +
                "INSERT INTO eix_occurrence (token_id, field, target_id) " +
                "SELECT t.id, 'f' || (n % 5), (n * 7919 % 50000)::text " +
                "FROM eix_token t CROSS JOIN generate_series(1, 10) n;\n" +
                "ANALYZE;");
            _initialized = true;
        }

        public void Dispose() => Db.Dispose();
    }
}

public sealed class PgSqlQueryPlanTest(PgSqlQueryTest.VolumeFixture fixture)
    : IClassFixture<PgSqlQueryTest.VolumeFixture>
{
    // capability check: seq scans are disabled so that the plan shows whether
    // an index can serve the predicate (at this volume a seq scan would still
    // be cheaper for trigram predicates; the planner switches to the trigram
    // index by itself at a few hundred thousand tokens)
    private string Explain(string sql)
    {
        fixture.Init();
        return string.Join("\n", fixture.Db.Strings(
            "SET enable_seqscan = off; EXPLAIN " + sql));
    }

    [Theory]
    [InlineData("value = 'abcd'", "eix_token_value_")]
    [InlineData("value LIKE 'abc%'", "eix_token_value_")]
    [InlineData("value ilike 'abc%'", "eix_token_value_trgm_idx")]
    [InlineData("value ilike '%bcde%'", "eix_token_value_trgm_idx")]
    [InlineData("value ilike '%cdef'", "eix_token_value_trgm_idx")]
    [InlineData("value ~ 'ab[0-9]cd'", "eix_token_value_trgm_idx")]
    [InlineData("value % 'abcdef12'", "eix_token_value_trgm_idx")]
    // the fuzzy condition built by PgSqlDialect
    [InlineData("(value % 'abcdef12' AND similarity(value, 'abcdef12') >= 0.5)",
        "eix_token_value_trgm_idx")]
    public void TokenSearches_UseIndexes(string where, string index)
    {
        string plan = Explain($"SELECT id FROM eix_token WHERE {where}");
        Assert.DoesNotContain("Seq Scan", plan);
        Assert.Contains(index, plan);
    }

    [Fact]
    public void OccurrenceSearch_ByTokens_UsesCoveringIndex()
    {
        string plan = Explain("SELECT DISTINCT o.target_id FROM eix_occurrence o " +
            "INNER JOIN eix_token t ON o.token_id = t.id " +
            "WHERE t.value ilike '%bcde%' AND o.field IN ('f1', 'f2')");
        Assert.DoesNotContain("Seq Scan", plan);
        Assert.Contains("eix_occurrence_token_field_target_idx", plan);
    }

    [Fact]
    public void OccurrenceSearch_ByTarget_UsesIndex()
    {
        string plan = Explain(
            "SELECT token_id FROM eix_occurrence WHERE target_id = '123'");
        Assert.DoesNotContain("Seq Scan", plan);
        Assert.Contains("eix_occurrence_target_field_idx", plan);
    }
}
